class Solution:
    def minimumAverage(self, nums: List[int]) -> float:
        # Sort the array to easily access min and max elements
        nums.sort()

        # Calculate averages by pairing smallest with largest
        averages = []
        n = len(nums)

        for i in range(n // 2):
            # Pair the i-th smallest with the i-th largest
            average = (nums[i] + nums[n - 1 - i]) / 2
            averages.append(average)

        # Return the minimum average
        return min(averages)

