    def doesAliceWin(self, s: str) -> bool:
        # Alice wins if there is at least one vowel in the string
        # Because if there's a vowel, Alice can always remove a substring containing that vowel
        # (which has odd count of vowels)
        # If there are no vowels, Alice cannot make any move

        vowels = set('aeiou')

        for char in s:
            if char in vowels:
                return True

        return False

