class Solution:
    def doesAliceWin(self, s: str) -> bool:
        # Alice wins if she can make a move on her first turn
        # She can make a move if there exists a non-empty substring with odd vowels
        # This happens when the string contains at least one vowel (a, e, i, o, u)

        vowels = set('aeiou')

        # Check if there's at least one vowel in the string
        for char in s:
            if char in vowels:
                return True

        # If no vowels found, Alice cannot make a move
        return False
